 "content": "def transform(grid):
    """Connect consecutive marker cells along each row and column with color 3."""
    if not grid:
        return []
    from collections import Counter
    counts = Counter(value for row in grid for value in row)
    background = counts.most_common(1)[0][0]
    candidates = [value for value in counts if value != background]
    if not candidates:
        return [row[:] for row in grid]
    marker = max(candidates, key=counts.get)
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == marker]
        for a, b in zip(cols, cols[1:]):
            for c in range(a + 1, b):
                out[r][c] = 3
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == marker]
        for a, b in zip(rows, rows[1:]):
            for r in range(a + 1, b):
                out[r][c] = 3
    return out

if __name__ == "__main__":
